fun resultFor(ok: Boolean, attempt: Int, max: Int): String = when {
    ok -> "success"
    attempt < max -> "retry"
    else -> "failure"
}

fun main() {
    var attempt = 0
    val outcomes = listOf(false, false, true)
    val log = mutableListOf<String>()
    for (ok in outcomes) {
        attempt++
        log.add(resultFor(ok, attempt, 3))
    }
    println(log)
    println(resultFor(false, 3, 3))
    println(resultFor(false, 1, 1))
}
